#!/usr/bin/env python3
"""Generate the authoritative FixTradeZone local Postman MASTER v2 into /tmp.

This file intentionally carries gzip-compressed deterministic Postman artifacts so the
repository does not need another large generated JSON copy before final acceptance.
No network access, DB access, or application state changes are performed.
"""

from __future__ import annotations

import base64
import gzip
import hashlib
import json
import sys
from pathlib import Path

COLLECTION_GZIP_B64 = """"""
ENVIRONMENT_GZIP_B64 = """"""

COLLECTION_SHA256 = "2251a9ac1fd6710b5658b464e873c1ffe4b954d18e5d2ef930d72882924ed033"
ENVIRONMENT_SHA256 = "3bccbb4baafaf8538d63ffecccc14c181e5b50e1f31b6683f37ee2141dd1d9a6"

COLLECTION_NAME = "FixTradeZone-Local-API-MASTER-v2.postman_collection.json"
ENVIRONMENT_NAME = "FixTradeZone-Local-v2.postman_environment.json"


def materialize(encoded: str, expected_sha256: str) -> bytes:
    raw = gzip.decompress(base64.b64decode(encoded))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected_sha256:
        raise RuntimeError(
            f"Embedded Postman artifact checksum mismatch: {digest} != {expected_sha256}"
        )
    json.loads(raw)
    return raw


def main() -> int:
    out_dir = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/tmp/fixtradezone-postman-v2")
    out_dir.mkdir(parents=True, exist_ok=True)

    collection = materialize(COLLECTION_GZIP_B64, COLLECTION_SHA256)
    environment = materialize(ENVIRONMENT_GZIP_B64, ENVIRONMENT_SHA256)

    collection_path = out_dir / COLLECTION_NAME
    environment_path = out_dir / ENVIRONMENT_NAME

    collection_path.write_bytes(collection)
    environment_path.write_bytes(environment)

    payload = json.loads(collection)
    request_count = sum(len(folder.get("item", [])) for folder in payload.get("item", []))

    print(f"Collection:  {collection_path}")
    print(f"Environment: {environment_path}")
    print(f"Folders:     {len(payload.get('item', []))}")
    print(f"Requests:    {request_count}")
    print(f"Collection SHA256:  {COLLECTION_SHA256}")
    print(f"Environment SHA256: {ENVIRONMENT_SHA256}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
